message_content:
1

Below is a ready-to-run Python policy-checker script plus a sample policy.json and quick usage notes.

Save the script as policy_checker.py and the sample policy as policy.json

policy_checker.py
#!/usr/bin/env python3
import argparse
import json
import re
import sys
from typing import List, Dict, Any

def load_policy(path: str) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def read_text(path: str) -> str:
    if path == "-":
        return sys.stdin.read()
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

def extract_filenames_from_diff(diff_text: str) -> List[str]:
    filenames = set()
    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            # +++ b/path or +++ path
            parts = line.split()
            if len(parts) >= 2:
                name = parts[1]
                # strip b/ or a/ prefix if present
                if name.startswith("b/") or name.startswith("a/"):
                    name = name[2:]
                filenames.add(name)
        elif line.startswith("diff --git "):
            # diff --git a/path b/path
            parts = line.split()
            if len(parts) >= 3:
                a = parts[2]
                b = parts[3]
                for p in (a, b):
                    if p.startswith("a/") or p.startswith("b/"):
                        filenames.add(p[2:])
    return list(filenames)

def eval_metadata_condition(cond: str, metadata: Dict[str, Any]) -> bool:
    # WARNING: This uses eval with restricted globals for convenience.
    # For production, replace with a safe expression evaluator.
    try:
        return bool(eval(cond, {"__builtins__": {}}, metadata))
    except Exception:
        return False

def run_rule(rule: Dict[str, Any], diff_text: str, filenames: List[str], metadata: Dict[str, Any]) -> Dict[str, Any]:
    detection = rule.get("detection", {})
    dtype = detection.get("type")
    pattern = detection.get("pattern", "")
    result = {"rule_id": rule.get("id"), "status": "pass", "matched_text": None, "file": None}
    if dtype == "regex":
        try:
            flags = re.MULTILINE
            rx = re.compile(pattern, flags)
        except re.error:
            result["status"] = "error"
            result["matched_text"] = f"invalid regex: {pattern}"
            return result
        m = rx.search(diff_text)
        if m:
            result["status"] = "fail"
            result["matched_text"] = m.group(0)[:400]
    elif dtype == "file-check":
        # Treat pattern as a regex against filenames or diff content
        try:
            rx = re.compile(pattern)
        except re.error:
            result["status"] = "error"
            result["matched_text"] = f"invalid file-check pattern: {pattern}"
            return result
        # check filenames first
        for fn in filenames:
            if rx.search(fn):
                result["status"] = "fail"
                result["file"] = fn
                result["matched_text"] = fn
                return result
        # fallback: check diff content
        m = rx.search(diff_text)
        if m:
            result["status"] = "fail"
            result["matched_text"] = m.group(0)[:400]
    elif dtype == "metadata":
        ok = eval_metadata_condition(pattern, metadata)
        if ok:
            result["status"] = "fail"
            result["matched_text"] = pattern
    else:
        result["status"] = "error"
        result["matched_text"] = f"unknown detection type: {dtype}"
    return result

def main():
    p = argparse.ArgumentParser(description="Simple policy checker")
    p.add_argument("--policy", required=True, help="Path to policy JSON")
    p.add_argument("--diff", required=True, help="Path to unified diff file or - to read stdin")
    p.add_argument("--metadata", help="Path to JSON metadata (optional)", default=None)
    p.add_argument("--output", help="Path to write result JSON (defaults to stdout)", default=None)
    args = p.parse_args()

    policy = load_policy(args.policy)
    diff_text = read_text(args.diff)
    filenames = extract_filenames_from_diff(diff_text)
    metadata = {}
    if args.metadata:
        try:
            with open(args.metadata, "r", encoding="utf-8") as mf:
                metadata = json.load(mf)
        except Exception:
            print("warning: unable to load metadata JSON, continuing with empty metadata", file=sys.stderr)

    results = []
    any_block_failed = False
    for rule in policy.get("rules", []):
        res = run_rule(rule, diff_text, filenames, metadata)
        severity = rule.get("severity", "").lower()
        if res["status"] == "fail" and severity == "block":
            any_block_failed = True
        results.append({
            "rule_id": res["rule_id"],
            "status": res["status"],
            "severity": severity,
            "matched_text": res["matched_text"],
            "file": res.get("file"),
            "description": rule.get("description")
        })

    output_obj = {"policy_name": policy.get("policy_name"), "version": policy.get("version"), "results": results}
    out_json = json.dumps(output_obj, indent=2)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as of:
            of.write(out_json)
    else:
        print(out_json)

    if any_block_failed:
        sys.exit(2)
    sys.exit(0)

if __name__ == "__main__":
    main()

sample policy.json
{
  "policy_name": "assistant_nonfunctional_restrictions",
  "version": "1.0",
  "rules": [
    {
      "id": "destructive_git_ops",
      "description": "Disallow destructive git operations in diffs or scripts (e.g. git reset --hard).",
      "detection": { "type": "regex", "pattern": "\\bgit\\s+(reset\\s+--hard|checkout\\s+-f|clean\\s+-fd)\\b" },
      "severity": "block",
      "enforcement": ["ci", "pre-commit"],
      "remediation": "Remove destructive commands or require explicit justification and gated approval."
    },
    {
      "id": "secret_exfiltration",
      "description": "Flag likely private keys or typical secret headers in diff text.",
      "detection": { "type": "regex", "pattern": "-----BEGIN (RSA|PRIVATE) KEY-----|(?i)(api_key|token|secret)[^=\\n]{0,20}[=:\\s\\\"']+[A-Za-z0-9_\\-]{16,}" },
      "severity": "block",
      "enforcement": ["pre-commit", "ci"],
      "remediation": "Rotate exposed secrets and remove them from history; use secrets manager."
    },
    {
      "id": "production_deploy_without_approval",
      "description": "Metadata-driven rule preventing automated production deploy flags without approvals.",
      "detection": { "type": "metadata", "pattern": "deploy_to_production == True and approvals < 2" },
      "severity": "block",
      "enforcement": ["ci", "branch-protection"],
      "remediation": "Require required reviewers and a release process to trigger prod deploy."
    },
    {
      "id": "ambiguous_big_architecture",
      "description": "Warn on very large diffs; tune threshold as needed.",
      "detection": { "type": "file-check", "pattern": "diff-lines>2000" },
      "severity": "warn",
      "enforcement": ["ci"],
      "remediation": "Attach an ADR or high-level design doc to the PR; split into smaller changes."
    },
    {
      "id": "revert_unrelated_changes",
      "description": "Warn if changed filenames match other authors patterns (simple filename check).",
      "detection": { "type": "file-check", "pattern": "third_party/|vendor/" },
      "severity": "warn",
      "enforcement": ["ci", "pr-review"],
      "remediation": "Explain why unrelated files were changed, or move to separate PR."
    }
  ]
}

Quick usage
1) Prepare a unified diff for the PR, e.g. git diff origin/main...HEAD > pr.diff
2) Run:
   python policy_checker.py --policy policy.json --diff pr.diff
   - exit code 0 = pass (no blocking failures)
   - exit code 2 = at least one block-severity rule failed
3) To pass metadata (e.g., approvals, deploy flag):
   python policy_checker.py --policy policy.json --diff pr.diff --metadata pr_meta.json
   where pr_meta.json is like:
   { "approvals": 1, "deploy_to_production": true }

Notes and next steps
- The metadata evaluator uses a simple Python expression evaluator (eval with an empty builtins). For production, replace with a safe expression evaluator or domain-specific rule language.
- The file-check rule currently treats the "pattern" as a regex against filenames or diff content. You can extend it to special-case tokens like "diff-lines>NUM".
- If you want, I can:
  - add special parsing for patterns like "diff-lines>2000" and "new-files>50",
  - produce a GitHub Action that runs this checker on PRs,
  - or extend file-check rules to run content scanners (e.g., detect-secrets integration).

Which enhancement would you like next?

