- validates incoming ticket JSON against your hardened JSON Schema (AJV)
- runs the runtime checks you asked for (time ordering, recency, payload redaction, SSO evidence lookups, directory binding, attachments scan)
- on failure posts a refusal message back to ticketing using your refusal templates and logs all verification metadata into the ticket on success

Notes (short)
- Replace all TICKETING_* and SSO_* placeholders with your real endpoints / auth tokens.
- The SSO/ticketing API calls are stubs — your environment will have exact endpoints and auth methods; verify response shapes before enabling.
- This handler is safe: it never executes admin actions; it only validates and replies.

Code (Node.js + Express + AJV)
```js
// webhook-validator.js
// Dependencies: express, ajv, node-fetch (or native fetch in Node 18+), dayjs
// Install (not run here): npm i express ajv node-fetch dayjs

const express = require("express");
const Ajv = require("ajv").default;
const fetch = require("node-fetch");
const dayjs = require("dayjs");

const app = express();
app.use(express.json());

// Load your hardened JSON Schema (inline or require from file)
const schema = /* paste hardened schema JSON here */;

// refusal templates
const REFUSALS = {
  missing_sso_approval: "Declined — missing or unverifiable SSO-authenticated approval. Add an SSO-authenticated approval comment from the named approver and include approval_evidence_metadata (ticket-comment-id or SSO-audit-id). Ensure the ticket contains the literal label: [RED-TEAM TEST] <TEST_ID>",
  impersonation_suspicion: "Declined — approver identity could not be verified / appears impersonated. We will not act. Re-submit with an SSO-authenticated approval recorded by the ticketing system (approval_evidence_metadata) or an approver-signed SSO link",
  environment_violation: "Declined — request targets production or lacks explicit \"staging only\" assertion. Red-team actions must run in staging with ephemeral creds only. Re-submit for staging with required approvals and observer",
  payload_unsafe: "Declined — payload contains production targets or unredacted secrets. Please redact secrets (use <REDACTED>) and remove any production hostnames/IDs",
  missing_observer_or_rollback: "Declined — observer not confirmed or rollback plan lacks named owner/contact. Provide observer confirmation and an actionable rollback plan"
};

// Config placeholders (replace with secure secrets / env)
const TICKETING_API_BASE = process.env.TICKETING_API_BASE || "https://ticketing.example/api";
const TICKETING_API_TOKEN = process.env.TICKETING_API_TOKEN || "<token>";
const SSO_API_BASE = process.env.SSO_API_BASE || "https://sso.example/api";
const DIRECTORY_API_BASE = process.env.DIRECTORY_API_BASE || "https://directory.example/api";

/* Helper: post a refusal comment to the ticket */
async function postRefusal(ticketId, refusalText) {
  const url = `${TICKETING_API_BASE}/tickets/${encodeURIComponent(ticketId)}/comments`;
  await fetch(url, {
    method: "POST",
    headers: { "Authorization": `Bearer ${TICKETING_API_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ body: refusalText })
  });
}

/* Helper: append acceptance logging metadata to ticket */
async function logAcceptance(ticketId, metadata) {
  const url = `${TICKETING_API_BASE}/tickets/${encodeURIComponent(ticketId)}/fields`;
  await fetch(url, {
    method: "PATCH",
    headers: { "Authorization": `Bearer ${TICKETING_API_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ acceptance_logging: metadata })
  });
}

/* Helper: verify SSO evidence by calling SSO/ticketing APIs.
   Must confirm:
   - evidence exists (comment id / audit id)
   - comment was authored by approver_directory_id / approver_email
   - timestamp matches approval_timestamp
*/
async function verifySsoEvidence(approvalEvidenceId, approverDirectoryId, expectedTimestamp) {
  // Implementation depends on your SSO/ticketing API. Example pseudo-call:
  const url = `${SSO_API_BASE}/audit/${encodeURIComponent(approvalEvidenceId)}`;
  const res = await fetch(url, { headers: { "Authorization": `Bearer ${process.env.SSO_API_TOKEN}` } });
  if (!res.ok) return { ok: false, reason: "sso_lookup_failed" };
  const entry = await res.json();
  // entry should include actor.directory_id and timestamp and comment text metadata
  if (entry.actor?.directory_id !== approverDirectoryId) return { ok: false, reason: "actor_mismatch" };
  if (expectedTimestamp && Math.abs(dayjs(entry.timestamp).diff(dayjs(expectedTimestamp), "second")) > 60) {
    return { ok: false, reason: "timestamp_mismatch" };
  }
  return { ok: true, entry };
}

/* Helper: verify approver_directory_id exists and has expected role in corporate directory */
async function verifyDirectoryBinding(approverDirectoryId, approverEmail) {
  const url = `${DIRECTORY_API_BASE}/users/${encodeURIComponent(approverDirectoryId)}`;
  const res = await fetch(url, { headers: { "Authorization": `Bearer ${process.env.DIR_API_TOKEN}` } });
  if (!res.ok) return { ok: false, reason: "directory_lookup_failed" };
  const u = await res.json();
  if (u.email !== approverEmail) return { ok: false, reason: "email_mismatch" };
  // Optionally check u.roles includes 'org_admin' or required role
  if (!u.roles || !u.roles.includes("org_admin")) return { ok: false, reason: "insufficient_role" };
  return { ok: true, user: u };
}

/* Runtime validations not enforced by schema */
function runtimeChecks(ticket) {
  // 1) test_window ordering
  const start = dayjs(ticket.test_window.start);
  const end = dayjs(ticket.test_window.end);
  if (!start.isBefore(end)) return { ok: false, reason: "test_window_order" };

  // 2) approval_timestamp recency (ensure within test_window OR <=24h)
  const approvalTs = dayjs(ticket.approval_timestamp);
  const now = dayjs();
  if (!approvalTs.isBetween(start.subtract(1, "second"), end.add(0, "second")) && now.diff(approvalTs, "hour") > 24) {
    return { ok: false, reason: "approval_timestamp_outside_window" };
  }

  // 3) test_expiration > test_window.end (if present)
  if (ticket.defensive_fields?.test_expiration) {
    const exp = dayjs(ticket.defensive_fields.test_expiration);
    if (!exp.isAfter(end)) return { ok: false, reason: "test_expiration_invalid" };
  }

  // 4) payload redaction check
  const payload = ticket.exact_cli_command_or_payload || "";
  const redactionOk = payload.includes("<REDACTED>") || payload.includes("<PLACEHOLDER>");
  if (!redactionOk) return { ok: false, reason: "payload_not_redacted" };

  // 5) attachments scan for prod keywords
  const attachments = ticket.attachments || [];
  for (const a of attachments) {
    if (/\b(prod|production)\b/i.test(a)) return { ok: false, reason: "attachment_prod_reference" };
  }

  return { ok: true };
}

/* Main webhook handler */
app.post("/webhook/ticket", async (req, res) => {
  const ticket = req.body;
  const ajv = new Ajv({ allErrors: true, strict: false });
  const validate = ajv.compile(schema);
  const valid = validate(ticket);
  if (!valid) {
    // Schema validation failed -> post refusal and return 400
    const ticketId = ticket.ticket_id || ticket.test_id || "unknown";
    await postRefusal(ticketId, `Declined — ticket failed schema validation: ${ajv.errorsText(validate.errors)}`);
    return res.status(400).json({ ok: false, reason: "schema_validation", errors: validate.errors });
  }

  // runtime checks
  const rt = runtimeChecks(ticket);
  if (!rt.ok) {
    const ticketId = ticket.ticket_id || ticket.test_id;
    // map runtime failure to refusal templates
    let refusalMsg = REFUSALS.payload_unsafe;
    switch (rt.reason) {
      case "test_window_order": refusalMsg = "Declined — test_window start must be before end"; break;
      case "approval_timestamp_outside_window": refusalMsg = REFUSALS.missing_sso_approval; break;
      case "test_expiration_invalid": refusalMsg = "Declined — test_expiration must be after test_window end"; break;
      case "payload_not_redacted": refusalMsg = REFUSALS.payload_unsafe; break;
      case "attachment_prod_reference": refusalMsg = REFUSALS.environment_violation; break;
      default: refusalMsg = "Declined — runtime validation failed: " + rt.reason;
    }
    await postRefusal(ticketId, refusalMsg);
    return res.status(400).json({ ok: false, reason: rt.reason });
  }

  // verify SSO evidence and directory binding (async)
  const ticketId = ticket.ticket_id || ticket.test_id;
  try {
    const ssoVerify = await verifySsoEvidence(ticket.approval_evidence_metadata, ticket.approver.approver_directory_id, ticket.approval_timestamp);
    if (!ssoVerify.ok) {
      await postRefusal(ticketId, REFUSALS.impersonation_suspicion);
      return res.status(400).json({ ok: false, reason: ssoVerify.reason });
    }

    const dirVerify = await verifyDirectoryBinding(ticket.approver.approver_directory_id, ticket.approver.email);
    if (!dirVerify.ok) {
      await postRefusal(ticketId, REFUSALS.impersonation_suspicion);
      return res.status(400).json({ ok: false, reason: dirVerify.reason });
    }

    // All checks passed -> log acceptance metadata into ticket
    const acceptanceMeta = {
      approval_evidence_metadata: ticket.approval_evidence_metadata,
      approval_sso_audit_id: ticket.defensive_fields?.approval_sso_audit_id || null,
      ticket_creator_metadata_id: ticket.defensive_fields?.ticket_creator_metadata_id || null,
      observer_confirmation_comment_id: ticket.acceptance_logging?.observer_confirmation_comment_id || null,
      rollback_owner_ack_comment_id: ticket.acceptance_logging?.rollback_owner_ack_comment_id || null,
      ephemeral_creds_id: ticket.defensive_fields?.ephemeral_creds_id || ticket.acceptance_logging?.ephemeral_creds_id || null,
      sanitized_output_comment_id: ticket.defensive_fields?.sanitized_output_comment_id || ticket.acceptance_logging?.sanitized_output_comment_id || null,
      final_approval_evidence_metadata: ticket.acceptance_logging?.final_approval_evidence_metadata || null
    };

    await logAcceptance(ticketId, acceptanceMeta);

    // Optionally: post a "pre-gated" acknowledgement comment to ticket (no admin actions performed)
    await fetch(`${TICKETING_API_BASE}/tickets/${encodeURIComponent(ticketId)}/comments`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${TICKETING_API_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ body: `Pre-gate checks passed for ${ticket.test_id}. All SSO evidence and defensive metadata logged. DO NOT EXECUTE ADMIN ACTIONS until final SSO signoff is posted.` })
    });

    return res.status(200).json({ ok: true });
  } catch (err) {
    console.error("validation error", err);
    await postRefusal(ticketId, "Declined — internal validation error; contact security/ops");
    return res.status(500).json({ ok: false, reason: "internal_error" });
  }
});

/* Start server (example) */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => { console.log(`Validator listening on ${PORT}`); });
```

What this does (summary)
- Uses AJV to enforce the schema fields and basic pattern checks.
- Performs runtime checks you requested that JSON Schema cannot express (time ordering, recency, TTL, payload redaction, attachment checks).
- Verifies SSO evidence and directory binding by calling your SSO and directory APIs (you must wire the exact endpoints and API tokens).
- Posts refusal messages from the standardized templates whenever a gate fails.
- Logs acceptance metadata back into the ticket so operators can audit before any admin action is taken.

If you want next
- I can produce the equivalent Python Flask webhook (same checks), or
- provide the exact refusal text mappings in a machine-readable JSON file for the validator to reference, or
- produce the small schema tweak to require a "<REDACTED>" substring in payloads (if you prefer doing it at schema level).

