B) Local validator script (Python) — validates NDJSON records against your JSON Schema
- Requirements: Python 3.8+, pip install jsonschema
- Save your previously created JSON Schema to schema.json (the one you posted earlier). Save NDJSON file as alerts.ndjson.
- Save the script below to validate_ndjson.py and run locally: python validate_ndjson.py alerts.ndjson schema.json

#!/usr/bin/env python3
import sys
import json
from jsonschema import Draft7Validator, exceptions

def load_schema(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def validate_ndjson(ndjson_path, schema):
    validator = Draft7Validator(schema)
    errors_found = 0
    with open(ndjson_path, "r", encoding="utf-8") as f:
        line_no = 0
        while True:
            action_line = f.readline()
            if not action_line:
                break
            doc_line = f.readline()
            line_no += 2
            if not doc_line:
                print(f"[ERROR] Unexpected EOF after action line at line {line_no-1}")
                errors_found += 1
                break
            try:
                # action line may be small JSON like { "index": {...} }
                json.loads(action_line)
            except Exception as e:
                print(f"[ERROR] Invalid JSON on action line at approx line {line_no-1}: {e}")
                errors_found += 1
            try:
                doc = json.loads(doc_line)
            except Exception as e:
                print(f"[ERROR] Invalid JSON on document line at approx line {line_no}: {e}")
                errors_found += 1
                continue
            errors = sorted(validator.iter_errors(doc), key=lambda e: e.path)
            if errors:
                print(f"[INVALID] document starting near lines {line_no-1}-{line_no} has {len(errors)} validation errors:")
                for err in errors:
                    path = ".".join([str(p) for p in err.path]) or "(root)"
                    print(f"  - {path}: {err.message}")
                errors_found += 1
            else:
                print(f"[OK] document id (if present) request_id={doc.get('request_id','<none>')}")
    return errors_found

def main():
    if len(sys.argv) != 3:
        print("Usage: validate_ndjson.py <alerts.ndjson> <schema.json>")
        sys.exit(2)
    ndjson_path = sys.argv[1]
    schema_path = sys.argv[2]
    schema = load_schema(schema_path)
    errors = validate_ndjson(ndjson_path, schema)
    if errors:
        print(f"Validation completed: {errors} files with issues")
        sys.exit(1)
    else:
        print("Validation completed: all documents valid")
        sys.exit(0)

if __name__ == "__main__":
    main()

Validator usage notes
- The validator expects the bulk NDJSON form: action line then document line, repeated. It validates each document JSON against the provided Draft-07 schema.
- It prints per-document results and a summary exit code (0 success, 1 validation errors).
- Run in an offline, local staging environment only.

If you want, I can also:
- convert your JSON Schema into a small inline Python dict to embed in the script (so you only run one file), or
- output the ready-to-PUT curl command for the index template tailored to your cluster URL (you provide the host and auth method)

#!/usr/bin/env python3
"""
validate_ndjson_embedded.py

Local NDJSON validator for Elasticsearch/OpenSearch bulk files.
This single-file script embeds the JSON Schema (Draft-07) for assistant action logs
and validates each document (the document lines following bulk action lines)
in a bulk NDJSON file.

Usage:
  python validate_ndjson_embedded.py <alerts.ndjson>

Requirements:
  pip install jsonschema

Notes:
- The script expects the bulk format: one action line (e.g., {"index": {...}}) followed by one document line, repeated.
- The validator only checks document JSON against the embedded schema; it also checks that action lines are valid JSON.
- Run locally in an offline environment (no network calls).
"""

import sys
import json
from jsonschema import Draft7Validator, exceptions

SCHEMA_JSON = r'''
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AssistantActionLog",
  "type": "object",
  "required": ["timestamp","request_id","session_id","model_version","extracted_intent","policy_decision","audit"],
  "properties": {
    "timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "ISO8601 UTC time the request was handled"
    },
    "request_id": { "type": "string" },
    "session_id": { "type": "string" },
    "user_id": {
      "type": "string",
      "description": "Redacted or tokenized user identifier"
    },
    "raw_message_hash": {
      "type": "string",
      "pattern": "^sha256:[0-9a-fA-F]{64}$",
      "description": "SHA256 of the raw user message for integrity/correlation only"
    },
    "model_version": { "type": "string" },
    "extracted_intent": { "type": "string" },
    "intent_confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "embedded_resources": {
      "type": "object",
      "properties": {
        "urls": {
          "type": "array",
          "items": { "type": "string" }
        },
        "commands": {
          "type": "array",
          "items": { "type": "string" }
        }
      },
      "additionalProperties": false
    },
    "encoded_payloads": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "encoding": { "type": "string", "enum": ["base64","hex","urlencoded","other"] },
          "entropy_score": { "type": "number", "minimum": 0 },
          "sample": { "type": "string", "description": "optional redacted sample or hash" }
        },
        "required": ["encoding","entropy_score"],
        "additionalProperties": false
      }
    },
    "client_metadata": {
      "type": "object",
      "properties": {
        "ip_hash": { "type": "string", "description": "tokenized or hashed client IP" },
        "user_agent_hash": { "type": "string" },
        "locale": { "type": "string" }
      },
      "additionalProperties": false
    },
    "policy_decision": {
      "type": "object",
      "required": ["decision","rule_id","policy_rule_version"],
      "properties": {
        "decision": { "type": "string", "enum": ["allow","deny"] },
        "rule_id": { "type": "string" },
        "policy_rule_version": { "type": "string" },
        "reason": { "type": "string" }
      },
      "additionalProperties": false
    },
    "auth_check": {
      "type": "object",
      "properties": {
        "result": { "type": "string", "enum": ["sufficient","insufficient","not_required"] },
        "required_scope": { "type": "string" },
        "checked_at": { "type": "string", "format": "date-time" }
      },
      "additionalProperties": false
    },
    "sanitized_invocation": {
      "type": "object",
      "properties": {
        "target": { "type": "string", "description": "skill/target attempted (sanitized)" },
        "skill": { "type": "string" },
        "arguments_redacted": { "type": "string" },
        "invoked_at": { "type": "string", "format": "date-time" }
      },
      "additionalProperties": false
    },
    "sink_request_id": { "type": ["string","null"], "description": "egress sink/capture id if used" },
    "egress_blocked": { "type": "boolean", "description": "true if runtime/network blocked egress" },
    "human_review": {
      "type": "object",
      "properties": {
        "flag": { "type": "boolean" },
        "reviewer_id": { "type": ["string","null"] },
        "reviewed_at": { "type": ["string","null"], "format": "date-time" }
      },
      "additionalProperties": false
    },
    "alert_id": { "type": ["string","null"] },
    "siem_reference": { "type": ["string","null"] },
    "response_sent": { "type": "string" },
    "egress_trace": { "type": ["object","null"], "description": "optional pointer to egress/network logs (ids only)", "additionalProperties": true },
    "audit": {
      "type": "object",
      "required": ["logged_by","retention_days"],
      "properties": {
        "logged_by": { "type": "string" },
        "operator_override": { "type": ["object","null"], "properties": { "who": { "type": "string" }, "when": { "type": "string", "format": "date-time" } }, "additionalProperties": false },
        "retention_days": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}
'''

def load_schema_from_string(s):
    try:
        return json.loads(s)
    except Exception as e:
        print(f"[FATAL] Failed to parse embedded schema JSON: {e}")
        sys.exit(2)

def validate_ndjson_file(ndjson_path, schema):
    validator = Draft7Validator(schema)
    errors_found = 0
    try:
        with open(ndjson_path, "r", encoding="utf-8") as f:
            line_no = 0
            while True:
                action_line = f.readline()
                if not action_line:
                    break  # EOF
                line_no += 1
                # skip empty lines between blocks if any
                if action_line.strip() == "":
                    continue
                # read document line
                doc_line = f.readline()
                line_no += 1
                if not doc_line:
                    print(f"[ERROR] Unexpected EOF: action line at approx line {line_no-1} has no following document line")
                    errors_found += 1
                    break

                # Validate action line is valid JSON (we don't validate its structure further)
                try:
                    _ = json.loads(action_line)
                except Exception as e:
                    print(f"[ERROR] Invalid JSON on action line at approx line {line_no-1}: {e}")
                    errors_found += 1

                # Parse document JSON
                try:
                    doc = json.loads(doc_line)
                except Exception as e:
                    print(f"[ERROR] Invalid JSON on document line at approx line {line_no}: {e}")
                    errors_found += 1
                    continue

                # Validate document against schema
                errors = sorted(validator.iter_errors(doc), key=lambda e: e.path)
                if errors:
                    print(f"[INVALID] Document starting near lines {line_no-1}-{line_no} (request_id={doc.get('request_id','<none>')}) has {len(errors)} validation errors:")
                    for err in errors:
                        path = ".".join([str(p) for p in err.path]) or "(root)"
                        print(f"  - {path}: {err.message}")
                    errors_found += 1
                else:
                    print(f"[OK] document request_id={doc.get('request_id','<none>')}")
    except FileNotFoundError:
        print(f"[FATAL] File not found: {ndjson_path}")
        sys.exit(2)
    except Exception as e:
        print(f"[FATAL] Unexpected error while reading file: {e}")
        sys.exit(2)

    return errors_found

def main():
    if len(sys.argv) != 2:
        print("Usage: python validate_ndjson_embedded.py <alerts.ndjson>")
        sys.exit(2)

    ndjson_path = sys.argv[1]
    schema = load_schema_from_string(SCHEMA_JSON)

    print(f"[INFO] Validating '{ndjson_path}' against embedded schema...")
    errors = validate_ndjson_file(ndjson_path, schema)
    if errors:
        print(f"[RESULT] Validation completed: {errors} document(s) with issues")
        sys.exit(1)
    else:
        print("[RESULT] Validation completed: all documents valid")
        sys.exit(0)

if __name__ == "__main__":
    main()

