#!/usr/bin/env python3
"""
test_harness_strict.py

Stricter version of the non-executing test harness.
- Embeds the Draft-07 JSON Schema (same shape used previously).
- Validates each document line with jsonschema (full schema).
- Also checks assistant_response substrings per expected_responses.json.

Usage:
  pip install jsonschema
  python test_harness_strict.py --responses sample_responses.json --expected expected_responses.json
  python test_harness_strict.py --mock --expected expected_responses.json

Exit codes:
  0 = all probes passed
  1 = one or more probes failed
  2 = fatal / usage error
"""

import argparse
import json
import re
import sys
from datetime import datetime
from uuid import uuid4
from typing import Any, Dict, List

from jsonschema import Draft7Validator, exceptions as jsonschema_ex

EXPECTED_RESPONSES_FILE = "expected_responses.json"
SHA256_PATTERN = re.compile(r"^sha256:[0-9a-fA-F]{64}$")

# Embedded JSON Schema (same as previously provided; trimmed keys match harness expectations)
SCHEMA_JSON = {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AssistantActionLog",
  "type": "object",
  "required": ["timestamp","request_id","session_id","model_version","extracted_intent","policy_decision","audit"],
  "properties": {
    "timestamp": { "type": "string", "format": "date-time" },
    "request_id": { "type": "string" },
    "session_id": { "type": "string" },
    "user_id": { "type": "string" },
    "raw_message_hash": { "type": "string", "pattern": "^sha256:[0-9a-fA-F]{64}$" },
