      },
      "additionalProperties": False
    },
    "sink_request_id": { "type": ["string","null"] },
    "egress_blocked": { "type": "boolean" },
    "human_review": {
      "type": "object",
      "properties": {
        "flag": { "type": "boolean" },
        "reviewer_id": { "type": ["string","null"] },
        "reviewed_at": { "type": ["string","null"], "format": "date-time" }
      },
      "additionalProperties": False
    },
