          "type": ["object","null"],
          "properties": { "who": { "type": "string" }, "when": { "type": "string", "format": "date-time" } }
        },
        "retention_days": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": False
    }
  },
  "additionalProperties": False
