        resp_text = spec.get("expected_response_substring", "Refused")
        log = {
            "timestamp": datetime.utcnow().isoformat() + "Z",
            "request_id": f"req_{uuid4().hex[:8]}",
            "session_id": f"sess_{uuid4().hex[:8]}",
            "model_version": "assistant_runtime_v1.2",
            "extracted_intent": spec.get("extracted_intent", "test_intent"),
            "raw_message_hash": "sha256:" + "0"*64,
            "policy_decision": {"decision": spec.get("expected_policy_decision", "deny"),
                                "rule_id": spec.get("expected_rule_id", "test_rule"),
                                "policy_rule_version": spec.get("policy_rule_version","v1.0"),
                                "reason": "mocked"},
            "egress_blocked": True,
            "human_review": {"flag": spec.get("require_human_review", True)},
            "audit": {"logged_by": "assistant_runtime_v1.2", "retention_days": 90}
        }
        if spec.get("expected_policy_decision") == "allow":
            log["operator_override"] = {"who": "operator:REDACTED", "when": datetime.utcnow().isoformat() + "Z"}
            log["egress_blocked"] = False
            log["sink_request_id"] = "sink_mock_0001"
        docs.append({
            "probe_id": pid,
            "assistant_response": resp_text,
            "log_entry": log
        })
    return docs

def validate_with_schema(log_entry: Dict[str, Any], validator: Draft7Validator) -> List[str]:
    errors: List[str] = []
    try:
        for err in sorted(validator.iter_errors(log_entry), key=lambda e: e.path):
            path = ".".join([str(p) for p in err.path]) or "(root)"
            errors.append(f"{path}: {err.message}")
    except Exception as e:
        errors.append(f"schema validation error: {e}")
    return errors

def check_response_text(actual: str, expected_substr: str) -> bool:
    if expected_substr is None:
        return True
    return expected_substr.lower() in (actual or "").lower()

def run_checks(responses: List[Dict[str, Any]], expected_spec: Dict[str, Any], schema: Dict[str, Any], include_schema_errors: bool = True) -> Tuple[int, List[Dict[str, Any]]]:
    """
    Returns (failures_count, failures_list)
    failures_list contains dicts for each failed probe with details suitable for fail-report output.
    """
    total = 0
    failures = 0
    validator = Draft7Validator(schema)
    results = []
    failures_list: List[Dict[str, Any]] = []

    for entry in responses:
        total += 1
        pid = entry.get("probe_id")
        actual_resp = entry.get("assistant_response", "")
        log_entry = entry.get("log_entry", {})

        spec = expected_spec.get(pid)
        if spec is None:
            msg = f"unknown probe_id '{pid}'"
            results.append((pid, False, [msg]))
            failures += 1
            failures_list.append({
                "probe_id": pid,
                "assistant_response": actual_resp,
                "failure_messages": [msg],
                "log_meta": {
                    "request_id": log_entry.get("request_id"),
                    "session_id": log_entry.get("session_id"),
                    "model_version": log_entry.get("model_version"),
                    "raw_message_hash": log_entry.get("raw_message_hash")
                }
            })
            continue

        err_msgs: List[str] = []
        schema_errs = validate_with_schema(log_entry, validator)
        if not check_response_text(actual_resp, spec.get("expected_response_substring")):
            err_msgs.append(f"assistant_response did not include expected substring '{spec.get('expected_response_substring')}'")

        if schema_errs:
            # add summarised note
            err_msgs.append(f"schema validation failed with {len(schema_errs)} issue(s)")
            # include detailed schema errors optionally in failure record
        # additional required-field quick checks (presence/format) from spec
        for field in spec.get("required_log_fields", []):
            parts = field.split(".")
            cur = log_entry
            missing = False
            for p in parts:
                if isinstance(cur, dict) and p in cur:
                    cur = cur[p]
                else:
                    err_msgs.append(f"missing required field '{field}'")
                    missing = True
                    break
            if not missing and field == "raw_message_hash" and not SHA256_PATTERN.match(cur if isinstance(cur, str) else ""):
                err_msgs.append("raw_message_hash not a valid sha256:...")

        if err_msgs:
            failures += 1
            results.append((pid, False, err_msgs))

            # build compact failure record for report
            failure_record: Dict[str, Any] = {
                "probe_id": pid,
                "assistant_response": actual_resp,
                "failure_messages": err_msgs,
                "log_meta": {
                    "request_id": log_entry.get("request_id"),
                    "session_id": log_entry.get("session_id"),
                    "model_version": log_entry.get("model_version"),
                    "raw_message_hash": log_entry.get("raw_message_hash")
                }
            }
            if include_schema_errors and schema_errs:
                failure_record["schema_errors"] = schema_errs
            failures_list.append(failure_record)
        else:
            results.append((pid, True, []))

    # report
    print("="*60)
    print(f"Stricter test harness report: {len(responses)} probe(s) checked")
    print("="*60)
    for pid, ok, msgs in results:
        status = "PASS" if ok else "FAIL"
        print(f"{status}: {pid}")
        if msgs:
            for m in msgs:
                print(f"  - {m}")
    print("="*60)
    print(f"Summary: {len(responses) - failures} passed, {failures} failed")
    print("="*60)
    return failures, failures_list

def emit_ndjson_for_expected_logs(responses: List[Dict[str, Any]], out_path: str) -> None:
    with open(out_path, "w", encoding="utf-8") as f:
        for entry in responses:
            log = entry.get("log_entry", {})
            req_id = log.get("request_id", f"req_{uuid4().hex[:8]}")
            action = {"index": {"_index": "assistant_actions", "_id": req_id}}
            f.write(json.dumps(action) + "\n")
            f.write(json.dumps(log) + "\n")
    print(f"[INFO] Wrote NDJSON bulk file to {out_path}")

def write_fail_report(failures_list: List[Dict[str, Any]], out_path: str) -> None:
    """
    Write compact JSON report for failed probes.
    Each entry contains:
      - probe_id
      - assistant_response
      - failure_messages
      - log_meta: { request_id, session_id, model_version, raw_message_hash }
      - schema_errors (optional)
    """
    report = {
        "generated_at": datetime.utcnow().isoformat() + "Z",
        "failed_count": len(failures_list),
        "failures": failures_list
    }
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)
    print(f"[INFO] Wrote fail-report to {out_path}")

def main():
    parser = argparse.ArgumentParser(description="Stricter non-executing assistant probe test harness")
    parser.add_argument("--responses", help="JSON file (array) of actual assistant responses+logs")
    parser.add_argument("--mock", action="store_true", help="use built-in mock responses (matching expected_responses.json)")
    parser.add_argument("--emit-ndjson", help="path to write an NDJSON bulk file of the provided/mock log entries")
    parser.add_argument("--expected", help="path to expected responses JSON (default: expected_responses.json)",
                        default=EXPECTED_RESPONSES_FILE)
    parser.add_argument("--fail-report", help="path to write compact JSON fail-report if any probes fail")
    parser.add_argument("--no-schema-errors", action="store_true", help="do not include detailed schema errors in the fail-report")
    args = parser.parse_args()

    try:
        expected_spec = load_expected_responses(args.expected)
    except Exception as e:
        print(f"[FATAL] Failed to load expected responses spec '{args.expected}': {e}")
        sys.exit(2)

    if args.mock:
        responses = make_mock_responses(expected_spec)
    elif args.responses:
        try:
            responses = load_responses(args.responses)
        except Exception as e:
            print(f"[FATAL] Failed to load responses file: {e}")
            sys.exit(2)
    else:
        print("[FATAL] Either --responses or --mock must be provided")
        parser.print_help()
        sys.exit(2)

    include_schema_errors = not args.no_schema_errors
    failures_count, failures_list = run_checks(responses, expected_spec, SCHEMA_JSON, include_schema_errors=include_schema_errors)

    if args.emit_ndjson:
        emit_ndjson_for_expected_logs(responses, args.emit_ndjson)

    if failures_count and args.fail_report:
        # write compact fail report (redacted)
        write_fail_report(failures_list, args.fail_report)

    if failures_count:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()
